SELECT id, order_date, DENSE_RANK() OVER (PARTITION BY customer_id ORDER BY discount DESC) AS discount_dense_rank, FIRST_VALUE(discount) IGNORE NULLS OVER w_grp AS first_known_discount, PERCENT_RANK() OVER w_recent AS amount_percent_rank, DENSE_RANK() OVER (PARTITION BY status, customer_id ORDER BY amount NULLS LAST) AS amount_dense_rank, NTILE(10) OVER (PARTITION BY customer_id ORDER BY amount, id) AS amount_bucket FROM orders WINDOW w_grp AS (ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_recent AS (PARTITION BY store_id ORDER BY amount NULLS LAST);
